// Paints the artwork for each spiral card onto a 2D canvas, which the 3D spiral uses as a texture.
// There is one small painter per card (the PAINTERS table near the bottom): photo crop, rings,
// gradients, the number badge and the title. You usually do not edit this file.
// To change a card's photo, logo or colours, edit cardFaces.ts. Shared fonts and sizes are in cardStyle.ts.
// You only come here to change the shape of a drawing, or to give a new card its own painter.
import { CARD_FACES, type CardFace } from './cardFaces'
import { ACCENT, CARD_H, CARD_W, FONT, INK, OFFWHITE, type CardSpec, type Ctx } from './cardStyle'
import { TECH_ICONS } from '../lib/techIcons'

// ---------- loading ----------

const imageCache = new Map<string, Promise<HTMLImageElement>>()
function loadImage(src: string) {
  let p = imageCache.get(src)
  if (!p) {
    p = new Promise((resolve, reject) => {
      const img = new Image()
      img.onload = () => resolve(img)
      img.onerror = reject
      img.src = src
    })
    imageCache.set(src, p)
  }
  return p
}

// Canvas text only uses a web font once it is loaded, so wait for it first.
async function loadFonts() {
  const sample = 'ÁÉÍÓÚáéíóúñ¿¡Aa'
  try {
    await Promise.all([
      document.fonts.load('800 64px "Inter Variable"', sample),
      document.fonts.load('600 64px "Inter Variable"', sample),
    ])
  } catch {
    // fall back to the system font
  }
}

export async function paintCard(canvas: HTMLCanvasElement, spec: CardSpec, onUpdate: () => void) {
  await loadFonts()
  draw(canvas, spec, null)
  onUpdate()
  if (spec.id === 'skills') return paintSkillIcons(canvas, spec, onUpdate)
  const face = CARD_FACES[spec.id]
  const src = face?.photo?.src ?? face?.logo
  if (!src) return
  try {
    const img = await loadImage(src)
    draw(canvas, spec, img)
    onUpdate()
  } catch {
    // keep the base artwork if the image fails
  }
}

async function paintSkillIcons(canvas: HTMLCanvasElement, spec: CardSpec, onUpdate: () => void) {
  const icons = new Map<string, HTMLImageElement>()
  await Promise.all(
    spec.chips.map(async (chip) => {
      const t = TECH_ICONS[chip]
      if (!t) return
      try {
        icons.set(chip, await loadImage(`/tech-icons/${t.slug}.svg`))
      } catch {
        // skip logos that fail to load
      }
    }),
  )
  draw(canvas, { ...spec, icons }, null)
  onUpdate()
}

// ---------- one card: face, photo shade, number and title ----------

function draw(canvas: HTMLCanvasElement, spec: CardSpec, img: HTMLImageElement | null) {
  canvas.width = CARD_W
  canvas.height = CARD_H
  const ctx = canvas.getContext('2d')
  if (!ctx) return
  ctx.clearRect(0, 0, CARD_W, CARD_H)
  ctx.save()
  ctx.beginPath()
  ctx.roundRect(0, 0, CARD_W, CARD_H, 36)
  ctx.clip()

  const face = CARD_FACES[spec.id]
  if (face) PAINTERS[spec.id]?.(ctx, spec, face, img)
  if (face?.photo) {
    const g = ctx.createLinearGradient(0, CARD_H * 0.5, 0, CARD_H)
    g.addColorStop(0, 'rgba(0,0,0,0)')
    g.addColorStop(1, 'rgba(0,0,0,0.82)')
    ctx.fillStyle = g
    ctx.fillRect(0, CARD_H * 0.5, CARD_W, CARD_H * 0.5)
  }
  label(ctx, spec, face?.titleColor === 'dark')
  ctx.restore()
}

function label(ctx: Ctx, spec: CardSpec, light: boolean) {
  const fg = light ? INK : OFFWHITE
  const num = String(spec.index + 1).padStart(2, '0')
  ctx.font = `600 28px ${FONT}`
  ctx.textBaseline = 'middle'
  ctx.fillStyle = light ? 'rgba(10,10,10,0.12)' : 'rgba(255,255,255,0.16)'
  ctx.beginPath()
  ctx.roundRect(40, 40, 96, 48, 24)
  ctx.fill()
  ctx.fillStyle = fg
  ctx.textAlign = 'center'
  ctx.fillText(num, 88, 65)

  // Biggest size that fits in two lines and never overflows the card width.
  const maxW = CARD_W - 96
  ctx.textAlign = 'left'
  ctx.textBaseline = 'alphabetic'
  let size = 88
  let lines: string[] = []
  for (; size >= 40; size -= 4) {
    ctx.font = `800 ${size}px ${FONT}`
    lines = wrap(ctx, spec.title, maxW)
    if (lines.length <= 2 && lines.every((l) => ctx.measureText(l).width <= maxW)) break
  }
  ctx.fillStyle = fg
  const lineH = size * 0.98
  const startY = CARD_H - 56 - (lines.length - 1) * lineH
  lines.forEach((l, i) => ctx.fillText(l, 48, startY + i * lineH))
}

function wrap(ctx: Ctx, text: string, maxW: number) {
  const lines: string[] = []
  let line = ''
  for (const word of text.split(' ')) {
    const test = line ? `${line} ${word}` : word
    if (ctx.measureText(test).width > maxW && line) {
      lines.push(line)
      line = word
    } else line = test
  }
  if (line) lines.push(line)
  return lines
}

// ---------- card faces: one painter per card, colours come from cardFaces.ts ----------

function cover(ctx: Ctx, img: HTMLImageElement, fx: number, fy: number) {
  const s = Math.max(CARD_W / img.width, CARD_H / img.height)
  const dw = img.width * s
  const dh = img.height * s
  ctx.drawImage(img, -(dw - CARD_W) * fx, -(dh - CARD_H) * fy, dw, dh)
}

function photo(ctx: Ctx, _s: CardSpec, face: CardFace, img: HTMLImageElement | null) {
  ctx.fillStyle = face.background as string
  ctx.fillRect(0, 0, CARD_W, CARD_H)
  const p = face.photo!
  if (img) cover(ctx, img, p.fx, p.fy)
}

function tintedLogo(img: HTMLImageElement, w: number, h: number, color: string) {
  const c = document.createElement('canvas')
  c.width = w
  c.height = h
  const x = c.getContext('2d')!
  x.drawImage(img, 0, 0, w, h)
  x.globalCompositeOperation = 'source-in'
  x.fillStyle = color
  x.fillRect(0, 0, w, h)
  return c
}

function rings(ctx: Ctx, cx: number, cy: number, color: string, count = 5) {
  ctx.strokeStyle = color
  ctx.lineWidth = 3
  for (let i = 1; i <= count; i++) {
    ctx.beginPath()
    ctx.arc(cx, cy, i * 80, 0, Math.PI * 2)
    ctx.stroke()
  }
}

// Tech logo grid on a flat dark face: 6 columns, centred.
function skillLogos(ctx: Ctx, s: CardSpec) {
  const icons = s.icons
  if (!icons) return // still loading
  const T = 96
  const GAP = 14
  const COLS = 6
  const x0 = (CARD_W - (COLS * T + (COLS - 1) * GAP)) / 2
  s.chips
    .filter((c) => icons.has(c))
    .slice(0, COLS * 5)
    .forEach((chip, i) => {
      const x = x0 + (i % COLS) * (T + GAP)
      const y = 130 + Math.floor(i / COLS) * (T + GAP)
      ctx.fillStyle = '#1f1f1d'
      ctx.strokeStyle = '#34342f'
      ctx.lineWidth = 2
      ctx.beginPath()
      ctx.roundRect(x, y, T, T, 22)
      ctx.fill()
      ctx.stroke()
      ctx.drawImage(icons.get(chip)!, x + 21, y + 21, T - 42, T - 42)
    })
}

// Diagonal gradient from the face's first colour to its second.
function diagonal(ctx: Ctx, face: CardFace) {
  const [from, to] = face.background as string[]
  const g = ctx.createLinearGradient(0, 0, CARD_W, CARD_H)
  g.addColorStop(0, from)
  g.addColorStop(1, to)
  ctx.fillStyle = g
  ctx.fillRect(0, 0, CARD_W, CARD_H)
}

type Painter = (ctx: Ctx, s: CardSpec, face: CardFace, img: HTMLImageElement | null) => void

const PAINTERS: Record<string, Painter> = {
  intro: photo,
  about: photo,
  rowing: photo,
  experience(ctx, _s, face, img) {
    ctx.fillStyle = face.background as string
    ctx.fillRect(0, 0, CARD_W, CARD_H)
    rings(ctx, CARD_W, 0, face.lines!)
    if (img) {
      const w = 460
      const h = Math.round(w * (img.height / img.width || 48 / 84))
      ctx.drawImage(tintedLogo(img, w, h, face.logoColor!), (CARD_W - w) / 2, 300, w, h)
    }
  },
  education(ctx, _s, face, img) {
    // White centre fading to Marietta blue at the edges; the white title sits on the blue lower part.
    const [white, blueMid, blueEdge] = face.background as string[]
    const g = ctx.createRadialGradient(CARD_W / 2, 380, 0, CARD_W / 2, 380, 560)
    g.addColorStop(0, white)
    g.addColorStop(0.3, white)
    g.addColorStop(0.8, blueMid)
    g.addColorStop(1, blueEdge)
    ctx.fillStyle = g
    ctx.fillRect(0, 0, CARD_W, CARD_H)
    const shade = ctx.createLinearGradient(0, CARD_H * 0.7, 0, CARD_H)
    shade.addColorStop(0, 'rgba(8,30,70,0)')
    shade.addColorStop(1, 'rgba(8,30,70,0.3)')
    ctx.fillStyle = shade
    ctx.fillRect(0, CARD_H * 0.7, CARD_W, CARD_H * 0.3)
    const top = ctx.createLinearGradient(0, 0, 0, 240)
    top.addColorStop(0, 'rgba(8,30,70,0.7)')
    top.addColorStop(1, 'rgba(8,30,70,0)')
    ctx.fillStyle = top
    ctx.fillRect(0, 0, CARD_W, 240)
    if (img) {
      const w = 520
      const h = Math.round(w * (img.height / img.width))
      ctx.drawImage(img, (CARD_W - w) / 2, 380 - h / 2, w, h)
    }
  },
  skills(ctx, s, face) {
    ctx.fillStyle = face.background as string
    ctx.fillRect(0, 0, CARD_W, CARD_H)
    skillLogos(ctx, s)
  },
  projects(ctx, _s, face) {
    diagonal(ctx, face)
    ctx.strokeStyle = 'rgba(217,242,79,0.1)'
    ctx.lineWidth = 2
    for (let i = 1; i < 9; i++) {
      ctx.beginPath()
      ctx.moveTo(0, 150 + i * 56)
      ctx.lineTo(CARD_W, 150 + i * 56)
      ctx.stroke()
    }
    const pts = [0, 0.55, 0.35, 0.6, 0.45, 0.75, 0.62, 0.9].map((v, i) => [60 + i * 86, 560 - v * 320])
    ctx.beginPath()
    pts.forEach(([x, y], i) => (i ? ctx.lineTo(x, y - 40) : ctx.moveTo(x, y - 40)))
    for (let i = pts.length - 1; i >= 0; i--) ctx.lineTo(pts[i][0], pts[i][1] + 40)
    ctx.closePath()
    ctx.fillStyle = 'rgba(217,242,79,0.14)'
    ctx.fill()
    ctx.beginPath()
    pts.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)))
    ctx.strokeStyle = ACCENT
    ctx.lineWidth = 6
    ctx.lineJoin = 'round'
    ctx.stroke()
    pts.forEach(([x, y]) => {
      ctx.fillStyle = INK
      ctx.beginPath()
      ctx.arc(x, y, 11, 0, Math.PI * 2)
      ctx.fill()
      ctx.strokeStyle = ACCENT
      ctx.lineWidth = 4
      ctx.stroke()
    })
  },
  learning(ctx, _s, face) {
    diagonal(ctx, face)
    rings(ctx, CARD_W - 40, 220, face.lines!, 6)
  },
  leadership(ctx, _s, face) {
    diagonal(ctx, face)
    ctx.strokeStyle = face.lines!
    ctx.lineWidth = 3
    for (let i = 0; i < 5; i++) {
      ctx.beginPath()
      ctx.roundRect(CARD_W - 120 - i * 70, 150 + i * 70, 120 + i * 70, 120 + i * 70, 24)
      ctx.stroke()
    }
  },
  contact(ctx, _s, face) {
    ctx.fillStyle = face.background as string
    ctx.fillRect(0, 0, CARD_W, CARD_H)
    ctx.fillStyle = ACCENT
    ctx.beginPath()
    ctx.arc(CARD_W - 190, 330, 190, 0, Math.PI * 2)
    ctx.fill()
    ctx.fillStyle = INK
    ctx.font = `800 250px ${FONT}`
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    ctx.fillText('@', CARD_W - 190, 345)
  },
}
